import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.C0KMm31j.js";const i="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_03_01_prompt_contract.png",n="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_03_02_plan.png",c="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_03_03_workflows.png",p="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_03_04_context.png",l="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_03_05_feedback.png",s="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_03_06_done.png",g=JSON.parse('{"title":"一句话如何变成可信代码：Codex Prompt、上下文与 AGENTS.md 实战","description":"高质量 Prompt 不是写得像法律合同，也不是堆满模型术语，而是让代理知道目标、相关事实、真正边界和完成证据。OpenAI Docs 当前建议从自然语言开始，对重要任务补充 Goal、Context、Output 与 Boundaries，并通过后续反馈持续收敛。","frontmatter":{"title":"一句话如何变成可信代码：Codex Prompt、上下文与 AGENTS.md 实战","description":"高质量 Prompt 不是写得像法律合同，也不是堆满模型术语，而是让代理知道目标、相关事实、真正边界和完成证据。OpenAI Docs 当前建议从自然语言开始，对重要任务补充 Goal、Context、Output 与 Boundaries，并通过后续反馈持续收敛。","date":"2026-08-10","topic":"AI 底层学习","section":"OpenAI官方文档解读","readingTime":5,"source":"2026-08-10/ai_codex_official_03_prompting_context.md","status":"archived","cover":"/article-assets/2026-08-10/ai_codex_official_03_01_prompt_contract.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/ai/openai-codex-complete-guide"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"一句话如何变成可信代码：Codex Prompt、上下文与 AGENTS.md 实战"}],["meta",{"property":"og:description","content":"高质量 Prompt 不是写得像法律合同，也不是堆满模型术语，而是让代理知道目标、相关事实、真正边界和完成证据。OpenAI Docs 当前建议从自然语言开始，对重要任务补充 Goal、Context、Output 与 Boundaries，并通过后续反馈持续收敛。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/ai/openai-codex-complete-guide"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_03_01_prompt_contract.png"}],["meta",{"property":"article:published_time","content":"2026-08-10"}],["meta",{"name":"twitter:title","content":"一句话如何变成可信代码：Codex Prompt、上下文与 AGENTS.md 实战"}],["meta",{"name":"twitter:description","content":"高质量 Prompt 不是写得像法律合同，也不是堆满模型术语，而是让代理知道目标、相关事实、真正边界和完成证据。OpenAI Docs 当前建议从自然语言开始，对重要任务补充 Goal、Context、Output 与 Boundaries，并通过后续反馈持续收敛。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_03_01_prompt_contract.png"}],["meta",{"name":"robots","content":"noindex,follow"}]],"search":false,"prev":false,"next":false},"headers":[],"relativePath":"archive/ai-codex-official-03-prompting-context.md","filePath":"archive/ai-codex-official-03-prompting-context.md","lastUpdated":null}'),d={name:"archive/ai-codex-official-03-prompting-context.md"};function h(_,a,m,u,f,x){return t(),o("div",null,[...a[0]||(a[0]=[r('<blockquote><p>本文为历史归档版本，不再更新。请阅读<a href="/Nav2ArticlesSite/ai/openai-codex-complete-guide">当前版本</a>。</p></blockquote><h1 id="一句话如何变成可信代码-codex-prompt、上下文与-agents-md-实战" tabindex="-1">一句话如何变成可信代码：Codex Prompt、上下文与 AGENTS.md 实战 <a class="header-anchor" href="#一句话如何变成可信代码-codex-prompt、上下文与-agents-md-实战" aria-label="Permalink to &quot;一句话如何变成可信代码：Codex Prompt、上下文与 AGENTS.md 实战&quot;">​</a></h1><p>高质量 Prompt 不是写得像法律合同，也不是堆满模型术语，而是让代理知道目标、相关事实、真正边界和完成证据。OpenAI Docs 当前建议从自然语言开始，对重要任务补充 Goal、Context、Output 与 Boundaries，并通过后续反馈持续收敛。</p><h2 id="一、prompt-先描述结果" tabindex="-1">一、Prompt 先描述结果 <a class="header-anchor" href="#一、prompt-先描述结果" aria-label="Permalink to &quot;一、Prompt 先描述结果&quot;">​</a></h2><h3 id="_1-1-goal-定义最终状态" tabindex="-1">1.1 Goal 定义最终状态 <a class="header-anchor" href="#_1-1-goal-定义最终状态" aria-label="Permalink to &quot;1.1 Goal 定义最终状态&quot;">​</a></h3><p>不要只写“优化”“检查”或“完善”。目标应说明哪种行为需要改变、面向谁、在哪个范围生效，以及什么现象代表成功。</p><h3 id="_1-2-context-提供会改变判断的事实" tabindex="-1">1.2 Context 提供会改变判断的事实 <a class="header-anchor" href="#_1-2-context-提供会改变判断的事实" aria-label="Permalink to &quot;1.2 Context 提供会改变判断的事实&quot;">​</a></h3><p>相关文件、报错、接口契约、版本和现有测试都属于上下文。只提供真正影响结果的材料，比把整个仓库和所有日志塞进对话更有效。</p><h3 id="_1-3-output-定义交付形态" tabindex="-1">1.3 Output 定义交付形态 <a class="header-anchor" href="#_1-3-output-定义交付形态" aria-label="Permalink to &quot;1.3 Output 定义交付形态&quot;">​</a></h3><p>需要代码、报告、表格、补丁还是只读诊断，应明确说明。输出格式会影响代理的调查深度与工具选择。</p><h3 id="_1-4-boundaries-阻止真实损失" tabindex="-1">1.4 Boundaries 阻止真实损失 <a class="header-anchor" href="#_1-4-boundaries-阻止真实损失" aria-label="Permalink to &quot;1.4 Boundaries 阻止真实损失&quot;">​</a></h3><p>不能改的模块、禁止新增的依赖、需要保留的 API，以及删除、发布、发送消息前的确认要求，都是高价值边界。边界应少而关键，不要把每一步都写死。</p><p><img src="'+i+'" alt="图 1：Goal、Context、Output 与 Boundaries 组成任务合同"></p><h2 id="二、复杂任务先建立计划" tabindex="-1">二、复杂任务先建立计划 <a class="header-anchor" href="#二、复杂任务先建立计划" aria-label="Permalink to &quot;二、复杂任务先建立计划&quot;">​</a></h2><h3 id="_2-1-模糊任务需要先调查" tabindex="-1">2.1 模糊任务需要先调查 <a class="header-anchor" href="#_2-1-模糊任务需要先调查" aria-label="Permalink to &quot;2.1 模糊任务需要先调查&quot;">​</a></h3><p>面对陌生仓库或跨模块问题，让代理先定位入口、调用链、配置源、测试方式和风险，再给出计划。没有事实地图的计划只是格式完整的猜测。</p><h3 id="_2-2-计划必须连接验证" tabindex="-1">2.2 计划必须连接验证 <a class="header-anchor" href="#_2-2-计划必须连接验证" aria-label="Permalink to &quot;2.2 计划必须连接验证&quot;">​</a></h3><p>每个阶段都应说明改动点和验证方式。只列“分析、编码、测试”没有决策价值；真正计划会说明哪些文件受影响、何种失败会阻止下一阶段。</p><h3 id="_2-3-计划确认不代表无限授权" tabindex="-1">2.3 计划确认不代表无限授权 <a class="header-anchor" href="#_2-3-计划确认不代表无限授权" aria-label="Permalink to &quot;2.3 计划确认不代表无限授权&quot;">​</a></h3><p>批准方案不等于允许删除、发布或修改系统配置。任务范围与具体高风险动作仍应分别确认。</p><p><img src="'+n+'" alt="图 2：调查证据经过计划形成可验证阶段"></p><h2 id="三、不同工作流需要不同证据" tabindex="-1">三、不同工作流需要不同证据 <a class="header-anchor" href="#三、不同工作流需要不同证据" aria-label="Permalink to &quot;三、不同工作流需要不同证据&quot;">​</a></h2><h3 id="_3-1-探索任务交付事实地图" tabindex="-1">3.1 探索任务交付事实地图 <a class="header-anchor" href="#_3-1-探索任务交付事实地图" aria-label="Permalink to &quot;3.1 探索任务交付事实地图&quot;">​</a></h3><p>成果应包含入口、关键模块、数据流和待确认项，不应在尚未理解系统时顺手重构。</p><h3 id="_3-2-bug-修复先证明因果链" tabindex="-1">3.2 Bug 修复先证明因果链 <a class="header-anchor" href="#_3-2-bug-修复先证明因果链" aria-label="Permalink to &quot;3.2 Bug 修复先证明因果链&quot;">​</a></h3><p>可靠顺序是复现、定位、建立回归测试、最小修改和重新验证。靠近报错的警告不一定是根因，代理必须用源码和运行证据连接现象与原因。</p><h3 id="_3-3-重构先锁定外部行为" tabindex="-1">3.3 重构先锁定外部行为 <a class="header-anchor" href="#_3-3-重构先锁定外部行为" aria-label="Permalink to &quot;3.3 重构先锁定外部行为&quot;">​</a></h3><p>重构改变结构而不应改变契约。现有测试、调用方和公开 API 构成保护网；保护网不足时，先补能固定行为的测试。</p><h3 id="_3-4-测试关注失败语义" tabindex="-1">3.4 测试关注失败语义 <a class="header-anchor" href="#_3-4-测试关注失败语义" aria-label="Permalink to &quot;3.4 测试关注失败语义&quot;">​</a></h3><p>代理生成的测试可能只复述当前实现。人要检查断言是否真的验证需求，旧代码是否会失败，边界与错误分支是否被覆盖。</p><p><img src="'+c+'" alt="图 3：探索、修复、重构与测试对应不同证据链"></p><h2 id="四、上下文管理决定长任务质量" tabindex="-1">四、上下文管理决定长任务质量 <a class="header-anchor" href="#四、上下文管理决定长任务质量" aria-label="Permalink to &quot;四、上下文管理决定长任务质量&quot;">​</a></h2><h3 id="_4-1-上下文容量不等于上下文质量" tabindex="-1">4.1 上下文容量不等于上下文质量 <a class="header-anchor" href="#_4-1-上下文容量不等于上下文质量" aria-label="Permalink to &quot;4.1 上下文容量不等于上下文质量&quot;">​</a></h3><p>无关文件、重复日志和过期结论会淹没关键约束。上下文工程的目标是提高信噪比，而不是追求最大输入量。</p><h3 id="_4-2-稳定事实应写入项目文件" tabindex="-1">4.2 稳定事实应写入项目文件 <a class="header-anchor" href="#_4-2-稳定事实应写入项目文件" aria-label="Permalink to &quot;4.2 稳定事实应写入项目文件&quot;">​</a></h3><p>项目规范写入 <code>AGENTS.md</code>，进度写入 <code>ROADMAP.md</code>，架构决策进入专门文档，验证结果保留为可定位记录。这样任务不依赖模型永久记住长对话。</p><h3 id="_4-3-阶段边界适合压缩历史" tabindex="-1">4.3 阶段边界适合压缩历史 <a class="header-anchor" href="#_4-3-阶段边界适合压缩历史" aria-label="Permalink to &quot;4.3 阶段边界适合压缩历史&quot;">​</a></h3><p>完成调查或一个实现阶段后，保留目标、决策、改动、证据和待办，压缩失败尝试与重复输出。压缩不能丢失风险和未完成事项。</p><p><img src="'+p+'" alt="图 4：原始材料经过筛选和压缩形成高信噪上下文"></p><h2 id="五、反馈应减少歧义" tabindex="-1">五、反馈应减少歧义 <a class="header-anchor" href="#五、反馈应减少歧义" aria-label="Permalink to &quot;五、反馈应减少歧义&quot;">​</a></h2><p>“不对”“再优化”几乎没有新信息。有效反馈会指出具体文件、实际行为、预期行为和违反的边界。桌面 Diff 中的行级评论、失败测试和可复现日志，都是比情绪评价更好的反馈。</p><p>当用户在 Codex 工作期间追加消息时，还要区分 Steer 与 Queue：前者改变当前运行方向，后者等待下一轮。方向性修正应及时 Steering，独立新任务应排队或创建新 Thread。</p><p><img src="'+l+'" alt="图 5：证据反馈持续压缩任务歧义"></p><h2 id="六、完成条件必须由外部证据定义" tabindex="-1">六、完成条件必须由外部证据定义 <a class="header-anchor" href="#六、完成条件必须由外部证据定义" aria-label="Permalink to &quot;六、完成条件必须由外部证据定义&quot;">​</a></h2><p>代理停止输出不代表任务完成。每项要求应能对应 Diff、测试、构建、运行日志或人工检查；无法验证的部分要明确说明，未完成项不能藏在总结中。</p><p>一条成熟的任务链是：目标可观察、上下文可定位、边界可执行、计划可检查、修改可审查、验证可重复。Prompt 的价值最终体现在返工减少，而不是文本长度增加。</p><p><img src="'+s+'" alt="图 6：目标通过调查、实施、验证与 Review 形成交付"></p><h2 id="七、官方参考资料" tabindex="-1">七、官方参考资料 <a class="header-anchor" href="#七、官方参考资料" aria-label="Permalink to &quot;七、官方参考资料&quot;">​</a></h2><p><a href="https://learn.chatgpt.com/docs/prompting" target="_blank" rel="noreferrer">OpenAI Docs：Prompting</a></p><p><a href="https://learn.chatgpt.com/docs/agent-configuration/agents-md" target="_blank" rel="noreferrer">OpenAI Docs：AGENTS.md</a></p>',50)])])}const q=e(d,[["render",h]]);export{g as __pageData,q as default};
